"""Sinh p2data.js (nội dung Lab tích hợp) từ labs/integrated/*.py. Chạy: python tools/build_p2.py"""
import json, os
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
F = ["orders_core.py", "step1_api_loop.py", "step2_mcp_server.py", "step3_multi_agent.py"]
d = {f: open(os.path.join(R, "labs", "integrated", f), encoding="utf8").read() for f in F}
open(os.path.join(R, "p2data.js"), "w", encoding="utf8").write(
    "/* generated by tools/build_p2.py — do not edit by hand */\nwindow.V10LAB=" + json.dumps(d, ensure_ascii=False) + ";\n")
print("p2data.js", sum(map(len, d.values())), "chars")
